BEGIN;

CREATE TABLE bashkia_bashkimi (
    bashkia_id      INTEGER PRIMARY KEY,
    bashkuar_ne_id  INTEGER NOT NULL,
    CONSTRAINT fk_bb_bashkia FOREIGN KEY (bashkia_id)
        REFERENCES bashkia (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT fk_bb_bashkuar_ne FOREIGN KEY (bashkuar_ne_id)
        REFERENCES bashkia (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT chk_bb_jo_vetja CHECK (bashkia_id <> bashkuar_ne_id)
);
COMMENT ON TABLE bashkia_bashkimi IS 'Bashkite qe ne regjistrin e aseteve shfaqen te nje bashki tjeter (p.sh. Patos te Fier)';

INSERT INTO bashkia_bashkimi (bashkia_id, bashkuar_ne_id)
SELECT a.id, z.id
  FROM (VALUES
    ('Dropull', 'Berat'),
    ('Poliçan', 'Berat'),
    ('Memaliaj', 'Tepelenë'),
    ('Këlcyrë', 'Përmet'),
    ('Libohovë', 'Gjirokastër'),
    ('Maliq', 'Korçë'),
    ('Rrogozhinë', 'Kavajë'),
    ('Fushë Arrës', 'Pukë'),
    ('Klos', 'Mat'),
    ('Prrenjas', 'Librazhd'),
    ('Cërrik', 'Elbasan'),
    ('Belsh', 'Elbasan'),
    ('Selenicë', 'Vlorë'),
    ('Patos', 'Fier'),
    ('Divjakë', 'Lushnjë')
  ) AS v (nga, ne)
  JOIN bashkia a ON a.emri = v.nga
  JOIN bashkia z ON z.emri = v.ne;

CREATE TABLE skema_ujitese (
    id                INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    bashkia_id        INTEGER       NOT NULL,
    bashkia_burim_id  INTEGER       NOT NULL,
    transferimi       VARCHAR(12)   NOT NULL,
    renditja          INTEGER       NOT NULL,
    kodi              VARCHAR(60)   NOT NULL,
    emertimi          VARCHAR(200)  NOT NULL,
    burimi            VARCHAR(200),
    km                NUMERIC(10,2),
    teren             BOOLEAN,
    perditesuar_km    NUMERIC(10,2),
    perdoruesi_id     BIGINT,
    krijuar_me        TIMESTAMPTZ   NOT NULL DEFAULT now(),
    ndryshuar_me      TIMESTAMPTZ,
    CONSTRAINT uq_skema_ujitese UNIQUE (bashkia_id, kodi, emertimi),
    CONSTRAINT fk_su_bashkia FOREIGN KEY (bashkia_id)
        REFERENCES bashkia (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT fk_su_bashkia_burim FOREIGN KEY (bashkia_burim_id)
        REFERENCES bashkia (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT fk_su_perdoruesi FOREIGN KEY (perdoruesi_id)
        REFERENCES perdoruesi (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT chk_su_transferimi CHECK (transferimi IN ('plota', 'pjeserisht')),
    CONSTRAINT chk_su_renditja CHECK (renditja > 0),
    CONSTRAINT chk_su_kodi CHECK (kodi = btrim(kodi) AND kodi <> ''),
    CONSTRAINT chk_su_emertimi CHECK (emertimi = btrim(emertimi) AND emertimi <> ''),
    CONSTRAINT chk_su_km CHECK (km IS NULL OR km >= 0),
    CONSTRAINT chk_su_perditesuar_km CHECK (perditesuar_km IS NULL OR (perditesuar_km >= 0 AND perditesuar_km <= COALESCE(km, 0))),
    CONSTRAINT chk_su_ndryshuar CHECK ((ndryshuar_me IS NULL) = (perdoruesi_id IS NULL))
);
CREATE INDEX idx_su_bashkia ON skema_ujitese (bashkia_id, transferimi, renditja);
COMMENT ON TABLE skema_ujitese IS 'Skemat ujitese te transferuara te bashkite (Regjistri i aseteve), nga skedaret Excel te bashkive';
COMMENT ON COLUMN skema_ujitese.bashkia_burim_id IS 'Bashkia e skedarit Excel nga erdhi skema';
COMMENT ON COLUMN skema_ujitese.transferimi IS 'plota = skeme e plote; pjeserisht = vetem kanale te dyta';
COMMENT ON COLUMN skema_ujitese.km IS 'Kanale te para dhe te dyta (km)';
COMMENT ON COLUMN skema_ujitese.teren IS 'Identifikuar ne teren';
COMMENT ON COLUMN skema_ujitese.perditesuar_km IS 'Km te perditesuara';

CREATE TABLE skema_ujitese_lloji (
    skema_id  INTEGER      NOT NULL,
    lloji     VARCHAR(10)  NOT NULL,
    renditja  INTEGER      NOT NULL,
    burimi    VARCHAR(200),
    CONSTRAINT pk_skema_ujitese_lloji PRIMARY KEY (skema_id, lloji),
    CONSTRAINT fk_sul_skema FOREIGN KEY (skema_id)
        REFERENCES skema_ujitese (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT chk_sul_lloji CHECK (lloji IN ('rezervuar', 'lume', 'stacion')),
    CONSTRAINT chk_sul_renditja CHECK (renditja > 0)
);
COMMENT ON TABLE skema_ujitese_lloji IS 'Llojet e skemes (rezervuar, lume, stacion pompimi) me renditjen dhe burimin si ne fletet e Excel';

CREATE TABLE skema_ujitese_historiku (
    id             BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    skema_id       INTEGER      NOT NULL,
    para           JSONB,
    pas            JSONB        NOT NULL,
    perdoruesi_id  BIGINT       NOT NULL,
    ndryshuar_me   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT fk_suh_skema FOREIGN KEY (skema_id)
        REFERENCES skema_ujitese (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    CONSTRAINT fk_suh_perdoruesi FOREIGN KEY (perdoruesi_id)
        REFERENCES perdoruesi (id) ON UPDATE RESTRICT ON DELETE RESTRICT
);
CREATE INDEX idx_suh_skema ON skema_ujitese_historiku (skema_id, ndryshuar_me);

CREATE TEMP TABLE imp_skema (bashkia TEXT, burim TEXT, transferimi TEXT, renditja INTEGER, kodi TEXT, emertimi TEXT, burimi TEXT, km NUMERIC, teren BOOLEAN, perditesuar_km NUMERIC) ON COMMIT DROP;
