INSERT INTO skema_ujitese (bashkia_id, bashkia_burim_id, transferimi, renditja, kodi, emertimi, burimi, km, teren, perditesuar_km)
SELECT b.id, s.id, i.transferimi, i.renditja, i.kodi, i.emertimi, i.burimi, i.km, i.teren, i.perditesuar_km
  FROM imp_skema i
  JOIN bashkia b ON b.emri = i.bashkia
  JOIN bashkia s ON s.emri = i.burim;

INSERT INTO skema_ujitese_lloji (skema_id, lloji, renditja, burimi)
SELECT su.id, l.lloji, l.renditja, l.burimi
  FROM imp_lloji l
  JOIN bashkia b ON b.emri = l.bashkia
  JOIN skema_ujitese su ON su.bashkia_id = b.id AND su.kodi = l.kodi AND su.emertimi = l.emertimi;

DO $$
BEGIN
  IF (SELECT count(*) FROM bashkia_bashkimi) <> 15 THEN RAISE EXCEPTION 'bashkia_bashkimi: % rreshta', (SELECT count(*) FROM bashkia_bashkimi); END IF;
  IF (SELECT count(*) FROM skema_ujitese) <> 1582 THEN RAISE EXCEPTION 'skema_ujitese: % rreshta', (SELECT count(*) FROM skema_ujitese); END IF;
  IF (SELECT count(*) FROM skema_ujitese_lloji) <> 1590 THEN RAISE EXCEPTION 'skema_ujitese_lloji: % rreshta', (SELECT count(*) FROM skema_ujitese_lloji); END IF;
END $$;

ALTER TABLE skema_formulari ADD COLUMN skema_id INTEGER;
UPDATE skema_formulari f
   SET skema_id = su.id
  FROM skema_ujitese su
 WHERE su.bashkia_id = f.bashkia_id AND su.kodi || '|' || su.emertimi = f.celesi;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM skema_formulari WHERE skema_id IS NULL) THEN
    RAISE EXCEPTION 'formulare pa skeme: %', (SELECT string_agg(celesi, ', ') FROM skema_formulari WHERE skema_id IS NULL);
  END IF;
END $$;

UPDATE skema_formulari_historiku h
   SET celesi = f.skema_id::text
  FROM skema_formulari f
 WHERE f.bashkia_id = h.bashkia_id AND f.celesi = h.celesi;
UPDATE skema_formulari SET celesi = skema_id::text;

ALTER TABLE skema_formulari
    ALTER COLUMN skema_id SET NOT NULL,
    ADD CONSTRAINT uq_sf_skema UNIQUE (skema_id),
    ADD CONSTRAINT fk_sf_skema FOREIGN KEY (skema_id)
        REFERENCES skema_ujitese (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
    ADD CONSTRAINT chk_sf_celesi CHECK (celesi = skema_id::text);

GRANT SELECT                                       ON bashkia_bashkimi        TO idmis_app;
GRANT SELECT, INSERT                               ON skema_ujitese           TO idmis_app;
GRANT UPDATE (kodi, emertimi, burimi, km, teren, perditesuar_km, perdoruesi_id, ndryshuar_me)
                                                   ON skema_ujitese           TO idmis_app;
GRANT SELECT, INSERT                               ON skema_ujitese_lloji     TO idmis_app;
GRANT UPDATE (burimi)                              ON skema_ujitese_lloji     TO idmis_app;
GRANT SELECT, INSERT                               ON skema_ujitese_historiku TO idmis_app;

COMMIT;
